def _normalized(value):
    """Возвращает имя объекта в форме, используемой интроспекцией базы."""

    return str(value or "").casefold()


def _table_names(connection):
    """Возвращает множество существующих таблиц без учёта регистра."""

    with connection.cursor() as cursor:
        return {_normalized(name) for name in connection.introspection.table_names(cursor)}


