    families = {
        "BigAutoField": {"BigAutoField", "BigIntegerField", "AutoField", "IntegerField"},
        "BigIntegerField": {"BigAutoField", "BigIntegerField", "AutoField", "IntegerField"},
        "UUIDField": {"UUIDField", "CharField"},
        "CharField": {"CharField", "TextField"},
        "DateTimeField": {"DateTimeField"},
    }
    return families.get(internal_type, {internal_type})


